def classify_triangle_by_sides(p1, p2, p3):
    def squared(x, y):
        return (x - y) ** 2

    a2 = squared(p1[0], p2[0]) + squared(p1[1], p2[1])
    b2 = squared(p2[0], p3[0]) + squared(p2[1], p3[1])
    c2 = squared(p3[0], p1[0]) + squared(p3[1], p1[1])

    sides = sorted((a2, b2, c2))
    distinct = {sides[0], sides[1], sides[2]}
    if len(distinct) == 1:
        return 'equilateral'
    if len(distinct) == 2:
        return 'isosceles'
    return 'scalene'
