def is_point_on_segment(p, a, b):
    # Test if p lies on the line through a and b.
    # Algorithm from https://stackoverflow.com/questions/49403344/how-to-check-if-a-point-is-on-a-line
    # and https://math.stackexchange.com/questions/3517612/how-to-test-if-a-point-is-on-segment-in-2d

    def dot(u, v):
        return u[0] * v[0] + u[1] * v[1]

    def det(u, v):
        return u[0] * v[1] - u[1] * v[0]

    if a == b:
        return a == p

    if not (0 <= dot(p - a, b - a) <= dot(b - a, b - a)):
        return False

    if det(b - a, p - a) != 0:
        return False

    return True

def subtract(u, v):
    return (u[0] - v[0], u[1] - v[1])
