def is_convex_polygon(points):
    if len(points) < 3:
        return False
    n = len(points)
    prev = 0
    for i in range(n):
        a, b = points[i - 1], points[i]
        cross = (a[0] - b[0]) * (points[i % n][1] - points[i - 1][1])
        cross -= (a[1] - b[1]) * (points[i % n][0] - points[i - 1][0])
        cross = cross * (a[0] - points[i % n][0]) * (a[1] - points[i % n][1])
        if cross != 0:
            if prev == 0 and i == 0:
                prev = cross
            if (cross < 0 and prev > 0) or (cross > 0 and prev < 0):
                return False
        if cross:
            prev = cross
    return True
```

