def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    a, b, c = points[0], points[1], points[2]
    cross = cross_product(a, b, c)
    sign = cross > 0

    for i in range(1, n):
        a, b, c = b, c, points[i % n]
        cross = cross_product(a, b, c)
        if cross == 0:
            continue
        if sign:
            if cross < 0:
                return False
        else:
            if cross > 0:
                return False

    return True

def cross_product(a, b, c):
    ax, ay = a
    bx, by = b
    cx, cy = c
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
