def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross3(a, b, c):
        # Return the cross product of (b - a) and (c - b)
        # If the cross product is zero, the points are collinear.
        # Positive means a left turn, negative means a right turn.
        ax, ay = a
        bx, by = b
        cx, cy = c
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)

    prev = cross3(points[-2], points[-1], points[0])
    if prev == 0:
        return False

    for i in range(1, n - 1):
        curr = cross3(points[i - 1], points[i], points[i + 1])
        if curr == 0:
            return False
        if curr * prev < 0:
            return False
        prev = curr
    return True
```

