def nearest_point(target, points):
    x0, y0 = target
    def distance(point):
        x, y = point
        return (x - x0) ** 2 + (y - y0) ** 2  # squared distance
    best = points[0]
    for point in points:
        d = distance(point)
        if d < distance(best):
            best = point
    return best
```

