def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid1[0]:
        return not grid2 or not grid2[0]
    m, n = len(grid1), len(grid1[0])
    if len(grid2) != m or len(grid2[0]) != n:
        return False

    # Transposed and reversed: 90 degrees clockwise
    def rotate90(grid):
        return [[v for v in reversed(row)] for row in zip(*grid)]

    # Rotated twice: 180 degrees
    def rotate180(grid):
        return [[v for v in reversed(row)] for row in reversed(grid)]

    # Rotated thrice: 270 degrees clockwise
    def rotate270(grid):
        return [list(reversed(row)) for row in zip(*reversed(grid))]

    # Test for each rotation, including identity
    for _ in range(4):
        if any(grida == gridb for grida, gridb in zip(grid1, grid2)):
            return True
        grid1 = rotate90(grid1)

    return False
```

