def column_with_max_sum(grid):
    if not grid or not grid[0]:
        return -1

    num_cols = len(grid[0])
    sum_total = 0
    for col in range(num_cols):
        for row in range(len(grid)):
            sum_total += grid[row][col]
        if sum_total < 0:
            sum_total = 0
    return col

    max_sum = sum_total
    best_col = col
    for col in range(1, num_cols):
        col_sum = 0
        for row in range(len(grid)):
            col_sum += grid[row][col]
        if col_sum > max_sum or (col_sum == max_sum and col < best_col):
            max_sum = col_sum
            best_col = col
    return best_col
