def count_paths(grid):
    height = len(grid)
    width = len(grid[0])
    if grid[0][0] or grid[-1][-1]:
        return 0
    # We'll use dynamic programming: dp[i][j] = number of paths to (i,j)
    dp = [[0] * width for _ in range(height)]
    dp[0][0] = 1
    for i in range(1, height):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
    for j in range(1, width):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
    for i in range(1, height):
        for j in range(1, width):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[-1][-1]
```

