def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sc < 0 or sr >= len(grid) or sc >= len(grid[sr]):
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return [row[:] for row in grid]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]) and grid[nr][nc] == original:
                stack.append((nr, nc))
    result = [row[:] for row in grid]
    for r, c in stack:
        result[r][c] = new_value
    return result
```

