def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True

    height = len(grid)
    width = len(grid[0])

    # Get the two values in the first row
    vals = {grid[0][0], grid[0][1]}
    if len(vals) != 2:
        return False

    # Assign the two values to c0 and c1 based on (i + j) % 2
    c0 = grid[0][0]
    c1 = grid[0][1]

    for i in range(height - 1):
        for j in range(width - 1):
            if (i + j) % 2 == 0:
                expected = c0
            else:
                expected = c1
            if grid[i][j] != expected or grid[i][j+1] != expected or grid[i+1][j] != expected:
                return False
        if (i + width) % 2 == 0:
            expected = c0
        else:
            expected = c1
        if grid[i][width - 1] != expected:
            return False
    if (height + width) % 2 == 0:
        expected = c0
    else:
        expected = c1
    if grid[height - 1][width - 1] != expected:
        return False

    return True
```

