def compare_semver(v1, v2):
    # Split the version strings into their numeric components
    parts = [[], []]
    for i, version in enumerate((v1, v2)):
        parts[i] = list(map(int, version.split('.')))
    # Compare each component in turn
    for a, b in zip(parts[0], parts[1]):
        if a < b:
            return -1
        if a > b:
            return 1
    # Compare lengths of the two lists if they are not the same length
    if len(parts[0]) < len(parts[1]):
        return -1
    if len(parts[0]) > len(parts[1]):
        return 1
    return 0
```

