def parse_duration(s):
    hours = 0
    minutes = 0
    i = 0
    while i < len(s):
        if s[i] == 'h':
            hours = int(s[:i])
            i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
        elif s[i] == 'm':
            minutes = int(s[:i])
            i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
    return hours * 60 + minutes
