def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme_end = 0
        scheme = ''
    else:
        scheme = url[:scheme_end]

    host_end = url.find('/', scheme_end + 3)
    if host_end == -1:
        host_end = url.find('?', scheme_end + 3)
        if host_end == -1:
            host_end = len(url)
    host = url[scheme_end + 3:host_end]

    path_start = host_end
    path_end = url.find('?', path_start)
    if path_end == -1:
        path_end = len(url)
    path = url[path_start:path_end]
    if path_start == host_end:
        path = url[host_end:] if '/' in url[host_end:] else ''

    query = url[path_end + 1:] if '?' in url else ''

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

