def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'
    directions = 'NESW'
    dx, dy = 0, 1  # direction vector for north

    for c in commands:
        if c == 'L':
            facing = directions[(directions.index(facing) - 1) % 4]
        elif c == 'R':
            facing = directions[(directions.index(facing) + 1) % 4]
        elif c == 'F':
            x += dx
            y += dy

    # Get the direction vector for the new facing
    for i in range(4):
        if facing == directions[i]:
            dx, dy = directions[i - 1], directions[i + 3]  # wrap around
    return (x, y, facing)
