def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    count = 0
    # Keep track of the number of requests in the current window
    # using a queue; we pop elements from the front if they fall out of the window.
    for t in timestamps:
        while count > 0 and t - timestamps[-count] > window:
            count -= 1
        count += 1
        if count <= limit:
            allowed.append(True)
        else:
            allowed.append(False)
    return allowed
```

