def robot_vacuum_cleaned(commands, obstacles):
    dirs = [(0, 1), (-1, 0), (0, -1), (1, 0)]   # N, W, S, E
    x, y = 0, 0
    facing = 0    # N = 0
    cleaned = set((x, y))
    for c in commands:
        if c == 'L':
            facing = (facing + 3) % 4
        elif c == 'R':
            facing = facing % 4
        elif c == 'F':
            dx, dy = dirs[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
        cleaned.add((x, y))
    return len(cleaned)
