    for c in commands:
        if c == "L":
            dx, dy = -dy, dx
        elif c == "R":
            dx, dy = dy, -dx
        elif c == "F":
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
            cleaned.add((x, y))

    return len(cleaned)
