def parking_garage_fees(events, rate):
    parked = {}
    for op, car_id, time in events:
        if op == 'enter':
            if car_id not in parked:
                parked[car_id] = time
        elif op == 'exit':
            if car_id in parked:
                duration = time - parked[car_id]
                fee = duration * rate
                parked[car_id] = time
                yield car_id, fee
    result = {}
    for car_id, fee in parked.items():
        if car_id in parked and car_id in events:  # the car has just exited
            result[car_id] = fee
    return result
