def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    from itertools import count
    stops = []
    floor_set = set(requests)
    if direction == 1:
        for next_floor in count(start_floor, 1):
            if next_floor > top_floor:
                break
            if next_floor in floor_set:
                stops.append(next_floor)
    else:
        for next_floor in count(start_floor, -1):
            if next_floor < 1:
                break
            if next_floor in floor_set:
                stops.append(next_floor)
    return stops
