def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def is_light_green(t, duration):
        red, green, yellow = duration
        cycle = red + green + yellow
        remainder = t % cycle
        return red <= remainder < red + green

    count = 0
    for t in range(n_ticks):
        if is_light_green(t, durations_a) and is_light_green(t, durations_b):
            count += 1
    return count
